using DSAExperimentation.DataStructures.HashMap;
namespace DSAExperimentation.Tests.LeetCodeCoverage.CopyListWithRandomPointer;
public sealed partial class CopyListWithRandomPointerTests { [Fact] public void CopyRandomList_TwoNodes_CopiesNextAndRandomLinks(){var a=new Node(7);var b=new Node(13);a.Next=b;b.Random=a;var c=Copy(a)!;Assert.NotSame(a,c);Assert.Equal(7,c.Value);Assert.Equal(13,c.Next!.Value);Assert.Same(c,c.Next.Random);} private static Node? Copy(Node? head){var map=new HashMap<Node,Node>();Node? Clone(Node? n){if(n is null)return null;if(map.TryGetValue(n,out var existing))return existing;var clone=new Node(n.Value);map.Set(n,clone);clone.Next=Clone(n.Next);clone.Random=Clone(n.Random);return clone;}return Clone(head);} private sealed class Node(int value){public int Value{get;}=value;public Node? Next{get;set;}public Node? Random{get;set;}} }
